        "analysis": "本题主要考查了正负数的意义，有理数的运算，绝对值等知识点，熟练掌握正负数的意义，有理数的运算，绝对值是解决此题的关键．<br>（1）首先根据正、负数运算的方法，把当天的行驶记录相加；然后根据正、负数的意义，判断出B地在A地的哪个方向，它们相距多少千米即可；<br>（2）首先求出当天行驶记录的绝对值的和，然后根据乘法的意义，用汽车行驶的路程乘以行驶每千米耗油量，求出该天共耗油多少升即可．",
        "detail": "（1）解：（1）∵$+18+(-9)+(+7)+(-14)+(-6)+(+13)+(-6)+(-8)+(-2)$<br>$=18+7+13+(-9-14-6-6-8-2)$<br>$=38+(-45)=-7$，<br>$|-7|=7$，<br>∴$B$地在A地正南方向，它们相距$7km$；<br>（2）∵$|+18|+|-9|+|+7|+|-14|+|-6|+|+13|+|-6|+|-8|+|-2|$<br>$=18+9+7+14+6+13+6+8+2$<br>$=83$，<br>∵汽车行驶$1km$平均耗油$aL$，<br>∴汽车行驶$83km$平均耗油$83aL$．"
