        "detail": "解：$\\because$第$1$个图案中“$●$”有：$2+3\\times 0=2$颗，<br>第$2$个图案中“$●$”有：$2+3\\times 1=5$颗，<br>第$3$个图案中“$●$”有：$2+3\\times 2=8$颗，<br>$…$<br>第$n$个图案中“$●$”有$2+3(n-1)=(3n-1)$颗，<br>故答案为：$(3n-1)$．"
