        "detail": "解：由$U=IR$得<br>$R=\\frac{U}{I}$，<br>∴当电源电压U恒定不变，则电阻R和电流I两个量成反比例关系．<br>将$R=100,I=2.2$代入$R=\\frac{U}{I}$，得<br>$100=\\frac{U}{2.2}$<br>解得$U=220$，<br>∴$R=\\frac{220}{I}$，<br>当$I=2.5$时，$R=\\frac{220}{2.5}=88$．<br>故答案为：反比例，88．"
