        "answer": "(1)$7m$，正比例<br>(2)①670个；<br>②$(-100)+70+60+(-130)+80+140+(-50)=70$，<br>$\\frac{70}{7}=10>0$，<br>$\\therefore$生产线这一周平均每天的实际生产量比计划数多了10个；<br>(3)①反比例；<br>②当$a=4$时，$t=\\frac{70000}{4m}$，<br>由（2）①可知，$m=600$，<br>$\\therefore t=\\frac{70000}{4\\times 600}\\approx 29.2<30$，<br>$\\therefore$该企业能在规定时间内完成订单．",
