        "detail": "（1）解：$\\because$原计划每天生产$m$个产品，<br>则该生产线每周生产$7m$个产品，<br>设生产时间为t天，那么t天的生产总量为$y=tm$，<br>$\\because m>0$，<br>$\\therefore$生产的产品总量与生产的时间成正比例关系，<br>故答案为：$7m$，正比例；<br>（2）①$\\because$周一生产的产品数是500个，它与m相差$-100$个，<br>$\\therefore m=500+100=600$（个），<br>周二与m的值相差70个，<br>$\\therefore$周二生产的产品数是$600+70=670$（个）；<br>②略<br>（3）①智能化生产线每天的产量是半自动生产线计划生产量的$a$倍，<br>$\\therefore$智能化生产线每天的产量为$am$，<br>$\\because$订单总量为70000个，<br>$\\therefore$所用时间$t=\\frac{70000}{am}=\\frac{70000}{m}\\cdot \\frac{1}{a}$，<br>$\\therefore$这条智能化生产线完成订单所需时间与$a$成反比例关系；<br>②略<br>【点睛】本题考查了列代数式，正负数的实际应用，有理数加法的应用，正比例，反比例关系，熟练掌握相关定义，准确理解题意为解题关键．"
