        "type": "calc",
        "typeName": "解答题",
        "difficulty": "中等",
        "stem": "如图，在 $\\triangle ABC$ 中，$\\angle ABC=90^\\circ$，$AB=8$，$BC=12$，点 $B$ 在直线 $m$ 上，点 $M$ 是直线 $m$ 上点 $B$ 左边的一点，且 $BM=4$，$\\angle ABM=60^\\circ$。动点 $P$ 从点 $A$ 出发，以每秒 $2$ 个单位长度的速度沿折线 $AB-BC$ 向终点 $C$ 匀速运动；同时动点 $Q$ 从 $C$ 点出发，以每秒 $6$ 个单位长度的速度沿折线 $CB-BA$ 向终点 $A$ 匀速运动。两点到达相应的终点就分别停止运动，分别过点 $P$、点 $Q$ 作 $PD \\perp m$ 于点 $D$，$QE \\perp m$ 于点 $E$。设点 $P$ 的运动时间为 $t\\text{ s}(t>0)$。<div class=\"my-2\"><img src=\"assets/images/img_066_18d95a478d7e.png\" style=\"width:280px; max-width:100%; height:auto;\" class=\"block\" data-cx=\"2667000\" data-cy=\"1600200\" /></div>(1)用含 $t$ 的代数式表示 $BP$ 的长；<br>(2)当点 $Q$ 在边 $BC$ 上时，求证：$\\angle PBD=\\angle BQE$；<br>(3)当 $\\triangle PBD$ 与 $\\triangle BQE$ 全等时，直接写出 $t$ 的值。",
        "options": [],
        "answer": "(1)$8-2t$ 或 $2t-8$；(2)证明见解析；(3)$1$ 或 $\\frac{5}{2}$ 或 $8$",
        "analysis": "本题主要考查了全等三角形的性质、直角三角形的性质、一元一次方程等知识点，学会用分类讨论的思想思考问题是解题的关键。<br>(1)由题意分 $0<t\\le 4$ 和 $4<t\\le 10$ 两种情况列出代数式即可；<br>(2)由直角三角形的性质以及平角的性质即可解答；<br>(3)由全等三角形的性质分情况列出方程求解即可。",
        "detail": "(1)解：当点 $P$ 到点 $B$ 时，$t=8\\div 2=4$；<br>当点 $P$ 到点 $C$ 时，$t=\\frac{AB+BC}{2}=\\frac{8+12}{2}=10$；<br>当 $0<t\\le 4$ 时，$P$ 在 $AB$ 上，则 $AP=2t$，<br>∴ $BP=AB-AP=8-2t$；<br>当 $4<t\\le 10$ 时，点 $P$ 在 $BC$ 上，<br>∵ $AB=8$，<br>∴ $BP=2t-AB=2t-8$。<br>∴ $BP$ 的长为 $8-2t$ 或 $2t-8$；<br>(2)证明：∵ $QE \\perp m$，<br>∴ $\\angle BEQ=90^\\circ$，<br>∴ $\\angle BQE+\\angle EBQ=90^\\circ$，<br>∵ $\\angle ABC=90^\\circ$，<br>∴ $\\angle PBD+\\angle EBQ=90^\\circ$，<br>∴ $\\angle PBD=\\angle BQE$；<br>(3)解：当点 $P$ 到点 $B$ 时，$t=\\frac{8}{2}=4$，当点 $P$ 到点 $C$ 时，$t=\\frac{AB+BC}{2}=\\frac{8+12}{2}=10$；<br>当点 $Q$ 到点 $B$ 时，$t=\\frac{BC}{6}=\\frac{12}{6}=2$，当点 $Q$ 到点 $A$ 时，$t=\\frac{AB+BC}{6}=\\frac{8+12}{6}=\\frac{10}{3}$。<br>①当 $0<t\\le 2$ 时，点 $P$ 在 $AB$ 边上，点 $Q$ 在 $BC$ 边上，$PB=8-2t$，$BQ=12-6t$，<br>此时 $\\angle PBD=\\angle BQE$，$PD \\perp m$，$QE \\perp m$，则有 $\\triangle PBD \\cong \\triangle BQE$，<br>∴ $PB=BQ$，<br>∴ $8-2t=12-6t$，解得：$t=1$；<br>②当 $2<t\\le \\frac{10}{3}$ 时，点 $P$、$Q$ 都在 $AB$ 边上，$PB=8-2t$，$BQ=6t-12$，<br>此时 $\\triangle PBD \\cong \\triangle QBE$，<br>∴ $PB=BQ$，<br>∴ $8-2t=6t-12$，解得：$t=\\frac{5}{2}$；<br>③当 $\\frac{10}{3}<t\\le 4$ 时，点 $Q$ 到终点 $A$ 停止不动，点 $P$ 在 $AB$ 边上，此时两个三角形不全等；<br>④当 $4<t\\le 10$ 时，点 $Q$ 到终点 $A$ 停止不动，点 $P$ 在边 $BC$ 上，$PB=2t-8$，$BQ=AB=8$，<br>此时 $\\triangle PBD \\cong \\triangle BQE$，<br>∴ $PB=BQ$，<br>∴ $2t-8=8$，解得：$t=8$。<br>综上，当 $\\triangle PBD$ 与 $\\triangle BQE$ 全等时，$t$ 的值为 $1$ 或 $\\frac{5}{2}$ 或 $8$。",
        "number": 23,
