        "detail": "解：$\\because BD\\perp OA,CE\\perp OA,\\angle BOC=90^\\circ$，<br>$\\therefore \\angle BDO=\\angle OEC=90^\\circ$，$\\angle DBO+\\angle DOB=\\angle DOB+\\angle EOC=90^\\circ$，<br>$\\therefore \\angle DBO=\\angle EOC$，<br>在$\\triangle BOD$和$\\triangle OCE$中，<br>$\\begin{cases} \\angle BDO=\\angle OEC \\\\ \\angle DBO=\\angle EOC \\\\ OB=CO \\end{cases}$，<br>$\\therefore \\triangle BOD\\cong\\triangle OCE(\\text{AAS})$，<br>$\\therefore BD=OE=1.4\\text{ m},OD=CE=1.8\\text{ m}$，<br>$\\therefore DE=OD-OE=1.8-1.4=0.4(\\text{m})$，<br>$\\because$点$B$处距地面$1\\text{ m}$高，<br>$\\therefore$在$C$处距离地面的高度是$1+0.4=1.4(\\text{m})$，<br>答：小丽距离地面的高度是$1.4\\text{ m}$．"
