        "stem": "如图，在$\\triangle ABC$中，直线l垂直平分边$BC$，分别交$AC$，$BC$于点D，E，连接$BD$．<br><img src=\"assets/images/img_docx_ac47535a97b7.png\" data-cx=\"1228725\" data-cy=\"971550\" style=\"width:129px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\"><br>(1)若$AB=9$，$\\triangle ABD$的周长为19，则$AC$的长为______；<br>(2)若$\\angle ADB=90^\\circ$，求$\\angle ACB$的度数；<br>(3)已知点P在线段$DE$上，且点P在边$AC$的垂直平分线上，连接$PC$，试判断点P是否在边$AB$的垂直平分线上，并说明理由．",
