        "stem": "如图，在$\\triangle ABC$中，$\\angle ABC$的角平分线与$\\angle ACB$的外角平分线交于点D，过点D作$EF\\parallel BC$，交$AB$于E，交$AC$于F，若$BE=8, CF=6$，则$EF$的长是（   ）<br><img src=\"assets/images/img_docx_eb695142e2f9.png\" data-cx=\"1495425\" data-cy=\"923925\" style=\"width:157px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">",
