        "stem": "如图，在长方形$ABCD$中，$E$，$F$分别是$BC$，$AD$边上的点，连接$EF$，将长方形$ABCD$沿$EF$折叠，点$C$落在点$C^{'}$处，点$D$落在点$D^{'}$处，$EC^{'}$与$AD$边交于点$M$．若四边形$DCEF$的周长是$17cm$，$EF=5cm$，则四边形$MFD^{'}C^{'}$的周长为（   ）<br><img src=\"assets/images/img_docx_b49ede85433f.png\" data-cx=\"1276350\" data-cy=\"1076325\" style=\"width:134px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">",
