        "stem": "如图，在△$\\triangle ABC$中，O是$AC$上的任意一点（不与点A、C重合）过点O平行于$BC$的直线l分别与$\\angle BCA$、$\\triangle ABC$的外角$\\angle DCA$的平分线交于点E、F．若$OE=9$，则$OF$的长是（    ）<br><img src=\"assets/images/img_docx_dc9db36f5b6d.png\" data-cx=\"1990725\" data-cy=\"1000125\" style=\"width:209px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">",
