        "detail": "解：∵直线$l\\parallel BC$，<br>∴$\\angle OEC=\\angle ECB$，<br>∵$CE$平分$\\angle ACB$，<br>∴$\\angle OCE=\\angle BCE$，<br>∴$\\angle OEC=\\angle OCE$，<br>∴$OE=OC$，<br>同理：$OF=OC$，<br>∴$OE=OF=9$，<br>故选；D．"
