        "chapter": "15.3.3 等边三角形的性质",
        "stem": "如图，$\\angle MON=30^\\circ$，点$A_{1}、A_{2}、A_{3}…$在射线ON上，点$B_{1}、B_{2}、B_{3}…$在射线OM上，$\\triangle A_{1}B_{1}A_{2}$、$\\triangle A_{2}B_{2}A_{3}、\\triangle A_{3}B_{3}A_{4}…$均为等边三角形，从左起第1个等边三角形的边长记为$a_{1}$，第2个等边三角形的边长记为$a_{2}$，以此类推．若$OA_{1}=1$，则$a_{2016}=$（    ）<br><img src=\"assets/images/img_docx_e8826ccb2432.png\" data-cx=\"2085975\" data-cy=\"1200150\" style=\"width:219px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">",
        "options": [
            "A. $2^{2014}$",
            "B. $2^{2015}$",
            "C. $2^{2016}$",
            "D. $2^{2017}$"
        ],
