        "detail": "解：∵等边三角形$ABC$的边长为7，<br>∴$BC=7,\\angle B=\\angle C=60^\\circ$，<br>∵点E，F是$BC$边的三等分点，<br>∴$EF=\\frac{1}{3}BC=\\frac{7}{3}$，<br>∵$DE\\parallel AB,DF\\parallel AC$，<br>∴$\\angle DEF=\\angle B=60^\\circ ,\\angle DFE=\\angle C=60^\\circ$，<br>∴$\\angle DEF=\\angle DFE=60^\\circ$，<br>∴$\\triangle DEF$为等边三角形，<br>∴$DE=DF=EF=\\frac{7}{3}$，<br>∴$\\triangle DEF$的周长是：$3\\times EF=3\\times \\frac{7}{3}=7$，<br>故选：C．"
