        "stem": "如图，在平面直角坐标系中，直线$AB$与$x$轴的夹角为$60^\\circ$，且点$A$坐标为$(-2,0)$，点$B$在$x$轴上方，设$AB=2a$，那么点$B$的横坐标为（   ）<br><img src=\"assets/images/img_docx_769d175067bc.png\" data-cx=\"1238250\" data-cy=\"1228725\" style=\"width:130px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">",
