        "detail": "解：如图所示，过点A作$AH\\perp BC$于H，<br>∵$AB=AC$，$AH\\perp BC$，<br>∴$BH=CH=\\frac{1}{2}BC, \\angle AHD=90^\\circ$，<br>∵$\\angle ADC=60^\\circ$，<br>∴$\\angle HAD=180^\\circ -\\angle ADH-\\angle AHD=30^\\circ$，<br>∴$DH=\\frac{1}{2}AD=2$，<br>∴$CH=BH=BD+DH=3.5$，<br>∴$CD=DH+CH=5.5$，<br>故答案为：$5.5$．<br><img src=\"assets/images/img_docx_81e784d99bbe.png\" data-cx=\"1724025\" data-cy=\"1200150\" style=\"width:181px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">"
