        "chapter": "15.9三线合一",
        "stem": "如图，在 $\\triangle ABC$ 中，$AB = AC$，点 $D$ 是 $BC$ 边上的中点，线段 $AC$ 的垂直平分线交 $AD$ 于点 $E$，交 $AC$ 于点 $F$，连接 $BE$。求证：$AE = BE$。<br><img src=\"assets/images/img_docx_c3c94c22d8e0.png\" data-cx=\"874800\" data-cy=\"1339200\" style=\"width:92px;max-width:100%;height:auto\" class=\"inline-block align-middle my-1 rounded\">",
        "options": [],
        "answer": "见详解",
